import { useCallback, useEffect, useState } from 'react'
import type { ExpenseViewModel } from '../../application/ExpenseViewModel'
import type { NewExpense } from '../../application/ExpenseGateway'
import { useExpenseUseCases } from '../useExpenseUseCases/useExpenseUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpenseUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    let cancelled = false
    listExpenses
      .execute()
      .then((items) => !cancelled && setExpenses(items))
      .catch((e: unknown) => !cancelled && setLoadError(e instanceof Error ? e.message : 'Could not load expenses'))
      .finally(() => !cancelled && setLoading(false))
    return () => {
      cancelled = true
    }
  }, [listExpenses])

  const submit = useCallback(
    async (expense: NewExpense): Promise<boolean> => {
      setSubmitting(true)
      setSubmitError(null)
      try {
        const result = await submitExpense.execute(expense)
        if (!result.ok) {
          setFieldErrors(result.errors)
          return false
        }
        setFieldErrors({})
        setExpenses(await listExpenses.execute())
        return true
      } catch (e) {
        setSubmitError(e instanceof Error ? e.message : 'Could not submit the expense')
        return false
      } finally {
        setSubmitting(false)
      }
    },
    [listExpenses, submitExpense],
  )

  return { expenses, loading, loadError, fieldErrors, submitError, submitting, submit }
}
