export const ExpenseForm = ({ errors, submitting, onSubmit }: ExpenseFormProps) => {
  const id = useId()
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault()
    const created = await onSubmit({ label, amount: Number(amount), currency })
    if (created) {
      setLabel('')
      setAmount('')
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor={`${id}-label`}>Label</label>
        <input
          id={`${id}-label`}
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          aria-invalid={Boolean(errors.label)}
          aria-describedby={errors.label ? `${id}-label-error` : undefined}
        />
        {errors.label && <p id={`${id}-label-error`} role="alert">{errors.label}</p>}
      </div>
      <div>
        <label htmlFor={`${id}-amount`}>Amount</label>
